ALGORITHM RootSpectrum(m, B, depths)
  INPUT   m >= 1  number of normalized factors
          B >= 1  bound on the exponent n
          depths  list of replication depths / lattice refinements to report
  OUTPUT  a report of admissible exponents in each ambient setting

  1. FUNCTION Divisors(k)
  2.     small <- [] ; large <- []
  3.     d <- 1
  4.     WHILE d*d <= k DO
  5.         IF k mod d = 0 THEN
  6.             append d to small
  7.             IF d != k/d THEN append k/d to large
  8.         d <- d + 1
  9.     RETURN small ++ reverse(large)

 10. integerSpectrum <- { n in Divisors(m) : n <= B }
        // justified by: an n-th root exists over Z-exponents  iff  n | m

 11. FOR EACH N in depths DO
 12.     replicatedSpectrum[N] <- { n in Divisors(N*m) : n <= B }
        // an n-th root of V_N(prod) exists          iff  n | N*m
        // an n-th root supported in (1/N)Z exists   iff  n | N*m
        // the two criteria coincide: one invariant, two descriptions

 13. FOR n <- 1 TO B DO
 14.     criticalExponent[n] <- -m / n        (as a reduced fraction)
 15.     minimalDepth[n]     <- n / gcd(n, m)
        // least d with n | d*m; correctness: write g = gcd(n,m), n = g*a,
        // m = g*b with gcd(a,b) = 1; then n | m*d  iff  a | b*d  iff  a | d

 16. puiseuxSpectrum <- "every n >= 1"
        // the value group Q is divisible, so -m/n always exists

 17. RETURN (integerSpectrum, replicatedSpectrum, criticalExponent,
             minimalDepth, puiseuxSpectrum)

ALGORITHM ConstructRoot(tails, n, K)
  INPUT   tails  list of m coefficient sequences; tails[i] = (c_{i,0}, c_{i,1}, ...)
                 encoding the normalized series T_i = q^{-1} + c_{i,0} + c_{i,1} q + ...
          n >= 1 desired root exponent
          K >= 0 truncation order
  OUTPUT  (e, w) with e = -m/n and w = (w_0, ..., w_K), w_0 = 1,
          such that (q^e * w)^n = prod_i T_i  modulo q^{e + K + 1}

  1. m <- length(tails)

  // Step 1: the corrected product U = prod_i (q * T_i), a power series with U_0 = 1
  2. U <- (1, 0, 0, ..., 0)                       // length K+1
  3. FOR EACH tail IN tails DO
  4.     F <- (1, tail[0], tail[1], ..., tail[K-1])   // pad or truncate to length K+1
  5.     U <- TruncatedMul(U, F, K)

  // Step 2: the n-th root of U with constant term 1
  6. ASSERT U_0 = 1
  7. w <- (1, 0, 0, ..., 0)
  8. FOR k <- 1 TO K DO
  9.     P <- TruncatedPow(w, n, k)                   // binary exponentiation mod q^{k+1}
 10.     w_k <- (U_k - P_k) / n
        // valid because [q^k] w^n depends on w_k only via n * w_0^{n-1} * w_k = n * w_k

  // Step 3: restore the pole
 11. e <- -m / n                                     (reduced fraction)
 12. RETURN (e, w)

  // Verification (optional): TruncatedPow(w, n, K) = U, and
  //   e is an integer  <=>  n | m  <=>  the root lies in the ordinary Laurent field
